arguments.content:
/* WellStream Platform — Global Styles */
:root {
  --navy: #0D1B2A;
  --navy-mid: #1B2838;
  --navy-light: #243447;
  --brand-primary: #15295A;
  --accent-green: #6CC24A;
  --accent-blue: #00B4D8;
  --accent-blue-dark: #0077B6;
  --dark-gray: #3C424B;
  --text-primary: #FFFFFF;
  --text-secondary: #A8B2C1;
  --text-muted: #6B7A8D;
  --border-color: rgba(255,255,255,0.08);
  --card-bg: rgba(255,255,255,0.04);
  --card-hover: rgba(255,255,255,0.08);
  --radius: 8px;
  --radius-lg: 16px;
  --transition: 0.3s ease;
  --max-width: 1200px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-size: 16px; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: var(--navy);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent-blue); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--accent-green); }
img { max-width: 100%; height: auto; }
ul { list-style: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ---- HEADER / NAV ---- */
.site-header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: rgba(13,27,42,0.95); backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
  padding: 0 24px; height: 72px;
  display: flex; align-items: center; justify-content: center;
}
.nav-inner {
  max-width: var(--max-width); width: 100%;
  display: flex; align-items: center; justify-content: space-between;
}
.logo { font-size: 1.35rem; font-weight: 700; color: var(--text-primary); letter-spacing: -0.02em; }
.logo span { color: var(--accent-blue); }
.nav-links { display: flex; align-items: center; gap: 32px; }
.nav-links > a, .nav-dropdown > .nav-drop-label { font-size: 0.9rem; font-weight: 500; color: var(--text-secondary); cursor: pointer; transition: color var(--transition); background: none; border: none; font-family: inherit; }
.nav-links > a:hover, .nav-dropdown:hover > .nav-drop-label { color: var(--text-primary); }
.nav-dropdown { position: relative; }
.nav-drop-label { display: flex; align-items: center; gap: 4px; }
.nav-drop-label::after { content: ''; border-left: 4px solid transparent; border-right: 4px solid transparent; border-top: 5px solid var(--text-secondary); transition: transform var(--transition); }
.nav-dropdown:hover .nav-drop-label::after { transform: rotate(180deg); border-top-color: var(--text-primary); }
.nav-drop-menu {
  position: absolute; top: calc(100% + 8px); left: 50%; transform: translateX(-50%);
  background: var(--navy-mid); border: 1px solid var(--border-color); border-radius: var(--radius);
  padding: 8px 0; min-width: 200px;
  opacity: 0; visibility: hidden; transition: all var(--transition);
  box-shadow: 0 12px 32px rgba(0,0,0,0.4);
}
.nav-dropdown:hover .nav-drop-menu { opacity: 1; visibility: visible; }
.nav-drop-menu a { display: block; padding: 10px 20px; font-size: 0.875rem; color: var(--text-secondary); white-space: nowrap; }
.nav-drop-menu a:hover { background: var(--card-hover); color: var(--text-primary); }

.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 12px 28px; border-radius: 6px; font-weight: 600; font-size: 0.9rem;
  border: none; cursor: pointer; transition: all var(--transition); font-family: inherit;
  text-decoration: none;
}
.btn-primary { background: var(--accent-blue); color: #fff; }
.btn-primary:hover { background: var(--accent-blue-dark); color: #fff; transform: translateY(-1px); box-shadow: 0 4px 16px rgba(0,180,216,0.3); }
.btn-secondary { background: transparent; color: var(--accent-blue); border: 1px solid var(--accent-blue); }
.btn-secondary:hover { background: rgba(0,180,216,0.1); color: var(--accent-blue); }
.btn-green { background: var(--accent-green); color: #0D1B2A; }
.btn-green:hover { background: #5aad3a; color: #0D1B2A; transform: translateY(-1px); }
.btn-sm { padding: 8px 20px; font-size: 0.825rem; }

/* ---- MOBILE NAV ---- */
.nav-toggle { display: none; background: none; border: none; cursor: pointer; padding: 4px; }
.nav-toggle span { display: block; width: 24px; height: 2px; background: var(--text-primary); margin: 5px 0; transition: all var(--transition); border-radius: 2px; }
.nav-toggle.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.nav-toggle.active span:nth-child(2) { opacity: 0; }
.nav-toggle.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* ---- HERO ---- */
.hero {
  padding: 140px 24px 80px;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 50%, var(--brand-primary) 100%);
  position: relative; overflow: hidden; text-align: center;
}
.hero::before {
  content: ''; position: absolute; top: -50%; right: -20%; width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(0,180,216,0.08) 0%, transparent 70%);
  border-radius: 50%;
}
.hero::after {
  content: ''; position: absolute; bottom: -30%; left: -10%; width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(108,194,74,0.06) 0%, transparent 70%);
  border-radius: 50%;
}
.hero-content { position: relative; z-index: 1; max-width: 800px; margin: 0 auto; }
.hero-label { font-size: 0.75rem; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--accent-blue); margin-bottom: 16px; }
.hero h1 { font-size: clamp(2rem, 5vw, 3.25rem); font-weight: 800; line-height: 1.15; letter-spacing: -0.03em; margin-bottom: 20px; }
.hero h1 .gradient-text {
  background: linear-gradient(90deg, var(--accent-blue), var(--accent-green));
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero p { font-size: 1.1rem; color: var(--text-secondary); max-width: 640px; margin: 0 auto 32px; }
.hero-actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ---- SECTIONS ---- */
section { padding: 80px 24px; }
.section-label { font-size: 0.75rem; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--accent-blue); margin-bottom: 12px; }
.section-title { font-size: clamp(1.5rem, 3vw, 2.25rem); font-weight: 700; margin-bottom: 16px; letter-spacing: -0.02em; }
.section-subtitle { font-size: 1rem; color: var(--text-secondary); max-width: 680px; line-height: 1.7; }
.text-center { text-align: center; }
.mx-auto { margin-left: auto; margin-right: auto; }

/* ---- FEATURED BANNER ---- */
.featured-banner {
  background: linear-gradient(90deg, var(--brand-primary), var(--accent-blue-dark));
  padding: 24px 0; text-align: center;
  margin-top: -1px;
}
.featured-banner .container { display: flex; align-items: center; justify-content: center; gap: 24px; flex-wrap: wrap; }
.featured-banner h3 { font-size: 1.1rem; font-weight: 600; }
.featured-banner span { color: var(--accent-green); font-weight: 700; }

/* ---- USE CASE GRID ---- */
.use-case-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 48px;
}
.use-case-card {
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 32px; cursor: pointer;
  transition: all var(--transition); position: relative; overflow: hidden;
}
.use-case-card::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px;
  background: linear-gradient(90deg, var(--accent-blue), var(--accent-green));
  transform: scaleX(0); transition: transform var(--transition); transform-origin: left;
}
.use-case-card:hover { background: var(--card-hover); border-color: rgba(0,180,216,0.2); transform: translateY(-4px); }
.use-case-card:hover::before { transform: scaleX(1); }
.use-case-card .card-icon {
  width: 48px; height: 48px; border-radius: 12px;
  background: rgba(0,180,216,0.1); display: flex; align-items: center; justify-content: center;
  margin-bottom: 16px; font-size: 1.25rem;
}
.use-case-card h3 { font-size: 1.05rem; font-weight: 600; margin-bottom: 8px; }
.use-case-card p { font-size: 0.875rem; color: var(--text-secondary); line-height: 1.6; }

/* ---- PLATFORM DIAGRAM ---- */
.diagram-section { background: var(--navy-mid); }
.platform-diagram {
  display: flex; gap: 24px; margin-top: 48px; justify-content: center; flex-wrap: wrap;
}
.diagram-pillar {
  flex: 1; min-width: 260px; max-width: 340px;
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 32px; text-align: center;
  position: relative; transition: all var(--transition);
}
.diagram-pillar:hover { border-color: var(--accent-blue); transform: translateY(-4px); }
.diagram-pillar .pillar-icon {
  width: 64px; height: 64px; border-radius: 50%;
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-blue-dark));
  margin: 0 auto 20px; display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem; color: #fff;
}
.diagram-pillar h3 { font-size: 1.1rem; margin-bottom: 8px; }
.diagram-pillar p { font-size: 0.85rem; color: var(--text-secondary); }
.diagram-connector {
  display: flex; align-items: center; color: var(--accent-blue); font-size: 1.5rem;
  align-self: center;
}

/* ---- INDUSTRY TABS ---- */
.tabs-container { margin-top: 48px; }
.tab-nav { display: flex; gap: 4px; border-bottom: 2px solid var(--border-color); padding-bottom: 0; overflow-x: auto; }
.tab-btn {
  padding: 12px 24px; background: none; border: none; border-bottom: 2px solid transparent;
  color: var(--text-muted); font-weight: 500; font-size: 0.9rem; cursor: pointer;
  transition: all var(--transition); white-space: nowrap; font-family: inherit;
  margin-bottom: -2px;
}
.tab-btn:hover { color: var(--text-secondary); }
.tab-btn.active { color: var(--accent-blue); border-bottom-color: var(--accent-blue); }
.tab-panel { display: none; padding: 32px 0; animation: fadeIn 0.3s ease; }
.tab-panel.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ---- BENEFITS GRID ---- */
.benefits-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 24px; margin-top: 48px;
}
.benefit-card {
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 28px; transition: all var(--transition);
}
.benefit-card:hover { border-color: rgba(0,180,216,0.2); background: var(--card-hover); }
.benefit-icon {
  width: 44px; height: 44px; border-radius: 10px;
  background: rgba(0,180,216,0.1); display: flex; align-items: center; justify-content: center;
  margin-bottom: 16px; color: var(--accent-blue); font-size: 1.15rem;
}
.benefit-card h3 { font-size: 1rem; font-weight: 600; margin-bottom: 8px; }
.benefit-card p { font-size: 0.85rem; color: var(--text-secondary); }

/* ---- STATS ---- */
.stats-row { display: flex; gap: 48px; justify-content: center; flex-wrap: wrap; margin-top: 48px; }
.stat-circle {
  text-align: center; position: relative;
}
.stat-ring {
  width: 160px; height: 160px; position: relative; margin: 0 auto 16px;
}
.stat-ring svg { width: 100%; height: 100%; transform: rotate(-90deg); }
.stat-ring .ring-bg { fill: none; stroke: var(--border-color); stroke-width: 6; }
.stat-ring .ring-fill { fill: none; stroke: var(--accent-blue); stroke-width: 6; stroke-linecap: round; transition: stroke-dashoffset 1.5s ease; }
.stat-ring .ring-fill.green { stroke: var(--accent-green); }
.stat-value {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  font-size: 2.2rem; font-weight: 800; color: var(--text-primary);
}
.stat-circle p { font-size: 0.875rem; color: var(--text-secondary); max-width: 180px; }

/* ---- TIMELINE ---- */
.timeline { margin-top: 48px; max-width: 700px; }
.timeline-item { display: flex; align-items: flex-start; gap: 24px; margin-bottom: 32px; }
.timeline-duration {
  min-width: 120px; font-size: 1.5rem; font-weight: 800; color: var(--accent-blue);
  white-space: nowrap;
}
.timeline-bar-wrap { flex: 1; }
.timeline-bar-wrap h4 { font-size: 0.95rem; margin-bottom: 8px; }
.timeline-bar {
  height: 8px; border-radius: 4px; background: var(--border-color); overflow: hidden;
}
.timeline-bar .bar-fill {
  height: 100%; border-radius: 4px;
  background: linear-gradient(90deg, var(--accent-blue), var(--accent-green));
  transition: width 1.2s ease;
}

/* ---- ACCORDION ---- */
.accordion { margin-top: 48px; max-width: 800px; }
.accordion-item { border-bottom: 1px solid var(--border-color); }
.accordion-header {
  display: flex; justify-content: space-between; align-items: center;
  padding: 20px 0; cursor: pointer; width: 100%; background: none; border: none;
  color: var(--text-primary); font-size: 1.05rem; font-weight: 600;
  font-family: inherit; text-align: left; transition: color var(--transition);
}
.accordion-header:hover { color: var(--accent-blue); }
.accordion-header .acc-icon {
  width: 28px; height: 28px; border-radius: 50%;
  background: rgba(0,180,216,0.1); display: flex; align-items: center; justify-content: center;
  transition: all var(--transition); font-size: 0.9rem; color: var(--accent-blue); flex-shrink: 0;
}
.accordion-item.active .accordion-header .acc-icon { transform: rotate(45deg); background: var(--accent-blue); color: #fff; }
.accordion-body {
  max-height: 0; overflow: hidden; transition: max-height 0.4s ease, padding 0.3s ease;
}
.accordion-item.active .accordion-body { max-height: 300px; }
.accordion-body-inner { padding: 0 0 20px; color: var(--text-secondary); font-size: 0.9rem; line-height: 1.7; }

/* ---- TESTIMONIALS ---- */
.testimonial-carousel { margin-top: 48px; overflow: hidden; position: relative; }
.testimonial-track { display: flex; transition: transform 0.5s ease; }
.testimonial-card {
  min-width: 100%; padding: 40px; background: var(--card-bg);
  border: 1px solid var(--border-color); border-radius: var(--radius-lg);
}
.testimonial-card .quote { font-size: 1.15rem; font-style: italic; line-height: 1.7; margin-bottom: 20px; color: var(--text-primary); }
.testimonial-card .author { font-size: 0.875rem; color: var(--accent-blue); font-weight: 500; }
.carousel-dots { display: flex; gap: 8px; justify-content: center; margin-top: 24px; }
.carousel-dot {
  width: 10px; height: 10px; border-radius: 50%;
  background: var(--border-color); border: none; cursor: pointer;
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--accent-blue); transform: scale(1.2); }

/* ---- DATA LIFECYCLE DIAGRAM ---- */
.lifecycle-diagram {
  display: flex; align-items: center; justify-content: center;
  gap: 12px; margin-top: 48px; flex-wrap: wrap;
}
.lifecycle-node {
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius); padding: 16px 24px; text-align: center;
  transition: all var(--transition); min-width: 120px;
}
.lifecycle-node:hover { border-color: var(--accent-blue); background: var(--card-hover); }
.lifecycle-node .node-label { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; color: var(--accent-blue); margin-bottom: 4px; }
.lifecycle-node .node-title { font-size: 0.9rem; font-weight: 600; }
.lifecycle-arrow { color: var(--accent-blue); font-size: 1.25rem; }

/* ---- SECURITY FEATURES ---- */
.security-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 24px; margin-top: 32px;
}
.security-card {
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 28px; transition: all var(--transition);
}
.security-card:hover { border-color: rgba(0,180,216,0.2); }
.security-card .sec-icon {
  width: 44px; height: 44px; border-radius: 10px;
  background: rgba(0,180,216,0.1); display: flex; align-items: center; justify-content: center;
  margin-bottom: 16px; color: var(--accent-blue); font-size: 1.15rem;
}
.security-card h3 { font-size: 1rem; font-weight: 600; margin-bottom: 8px; }
.security-card p { font-size: 0.85rem; color: var(--text-secondary); line-height: 1.6; }

/* ---- ETL BENEFITS ---- */
.etl-benefits { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 24px; margin-top: 32px; }
.etl-item { display: flex; gap: 16px; align-items: flex-start; }
.etl-check {
  width: 32px; height: 32px; border-radius: 50%;
  background: rgba(108,194,74,0.15); display: flex; align-items: center; justify-content: center;
  color: var(--accent-green); font-size: 0.9rem; flex-shrink: 0; margin-top: 2px;
}
.etl-item h4 { font-size: 0.95rem; font-weight: 600; margin-bottom: 4px; }
.etl-item p { font-size: 0.85rem; color: var(--text-secondary); }

/* ---- DEMO FORM ---- */
.demo-section {
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
  min-height: calc(100vh - 72px);
  display: flex; align-items: center; justify-content: center;
  padding: 120px 24px 80px;
}
.demo-wrapper { max-width: 720px; width: 100%; }
.demo-form { margin-top: 40px; }
.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 16px; }
.form-group { display: flex; flex-direction: column; }
.form-group.full { grid-column: 1 / -1; }
.form-group label { font-size: 0.8rem; font-weight: 500; color: var(--text-secondary); margin-bottom: 6px; }
.form-group input, .form-group select, .form-group textarea {
  background: rgba(255,255,255,0.05); border: 1px solid var(--border-color);
  border-radius: 6px; padding: 12px 16px; color: var(--text-primary);
  font-size: 0.9rem; font-family: inherit; transition: all var(--transition);
  outline: none;
}
.form-group input:focus, .form-group select:focus, .form-group textarea:focus {
  border-color: var(--accent-blue); box-shadow: 0 0 0 3px rgba(0,180,216,0.15);
}
.form-group input::placeholder, .form-group textarea::placeholder { color: var(--text-muted); }
.form-group textarea { resize: vertical; min-height: 100px; }
.form-group .error-msg { font-size: 0.75rem; color: #f44; margin-top: 4px; display: none; }
.form-group.invalid input, .form-group.invalid select { border-color: #f44; }
.form-group.invalid .error-msg { display: block; }
.form-success { display: none; text-align: center; padding: 40px 0; }
.form-success h3 { color: var(--accent-green); margin-bottom: 12px; }

/* ---- CULTURE / CTA SECTIONS ---- */
.culture-section { background: var(--navy-mid); }
.culture-content { max-width: 700px; }
.renewables-cta {
  background: linear-gradient(135deg, rgba(108,194,74,0.1), rgba(0,180,216,0.1));
  border: 1px solid rgba(108,194,74,0.2); border-radius: var(--radius-lg);
  padding: 48px; max-width: 900px; margin: 0 auto;
}
.renewables-cta h3 { font-size: 1.5rem; margin-bottom: 12px; }
.renewables-cta p { color: var(--text-secondary); margin-bottom: 24px; }

/* ---- COMPLIANCE CTA ---- */
.compliance-cta {
  background: linear-gradient(135deg, rgba(0,180,216,0.1), rgba(21,41,90,0.3));
  border: 1px solid rgba(0,180,216,0.2); border-radius: var(--radius-lg);
  padding: 48px; text-align: center; margin-top: 48px;
}
.compliance-cta h3 { font-size: 1.5rem; margin-bottom: 12px; }
.compliance-cta p { color: var(--text-secondary); margin-bottom: 24px; max-width: 600px; margin-left: auto; margin-right: auto; }

/* ---- SUPPORT CONTACT ---- */
.support-section { background: var(--navy-mid); padding: 60px 24px; }
.support-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 32px; }
.support-card {
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 28px; text-align: center;
  transition: all var(--transition);
}
.support-card:hover { border-color: rgba(0,180,216,0.2); }
.support-card .region-icon { font-size: 1.5rem; margin-bottom: 12px; }
.support-card h4 { font-size: 1rem; margin-bottom: 4px; }
.support-card p { font-size: 0.85rem; color: var(--text-secondary); }

/* ---- FOOTER ---- */
.site-footer {
  background: var(--navy); border-top: 1px solid var(--border-color);
  padding: 64px 24px 32px;
}
.footer-grid { display: grid; grid-template-columns: 2fr repeat(3, 1fr); gap: 48px; margin-bottom: 48px; }
.footer-brand p { color: var(--text-secondary); font-size: 0.85rem; margin-top: 12px; max-width: 300px; }
.footer-col h4 { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 1px; color: var(--text-muted); margin-bottom: 16px; }
.footer-col a { display: block; font-size: 0.875rem; color: var(--text-secondary); padding: 4px 0; }
.footer-col a:hover { color: var(--accent-blue); }
.footer-bottom {
  display: flex; justify-content: space-between; align-items: center;
  border-top: 1px solid var(--border-color); padding-top: 24px;
  font-size: 0.8rem; color: var(--text-muted);
}
.footer-bottom a { color: var(--text-muted); margin-left: 16px; }
.footer-bottom a:hover { color: var(--accent-blue); }

/* ---- COOKIE BANNER ---- */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 9999;
  background: var(--navy-mid); border-top: 1px solid var(--border-color);
  padding: 20px 24px;
  transform: translateY(100%); transition: transform 0.4s ease;
}
.cookie-banner.visible { transform: translateY(0); }
.cookie-inner {
  max-width: var(--max-width); margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between; gap: 24px;
  flex-wrap: wrap;
}
.cookie-inner p { font-size: 0.85rem; color: var(--text-secondary); flex: 1; }
