}
.accordion-header:hover { color: var(--accent-blue); }
.accordion-header .acc-icon {
  width: 28px; height: 28px; border-radius: 50%;
  background: rgba(0,180,216,0.1); display: flex; align-items: center; justify-content: center;
  transition: all var(--transition); font-size: 0.9rem; color: var(--accent-blue); flex-shrink: 0;
}
.accordion-item.active .accordion-header .acc-icon { transform: rotate(45deg); background: var(--accent-blue); color: #fff; }
.accordion-body {
  max-height: 0; overflow: hidden; transition: max-height 0.4s ease, padding 0.3s ease;
}
.accordion-item.active .accordion-body { max-height: 300px; }
.accordion-body-inner { padding: 0 0 20px; color: var(--text-secondary); font-size: 0.9rem; line-height: 1.7; }

/* ---- TESTIMONIALS ---- */
.testimonial-carousel { margin-top: 48px; overflow: hidden; position: relative; }
.testimonial-track { display: flex; transition: transform 0.5s ease; }
.testimonial-card {
  min-width: 100%; padding: 40px; background: var(--card-bg);
  border: 1px solid var(--border-color); border-radius: var(--radius-lg);
}
.testimonial-card .quote { font-size: 1.15rem; font-style: italic; line-height: 1.7; margin-bottom: 20px; color: var(--text-primary); }
.testimonial-card .author { font-size: 0.875rem; color: var(--accent-blue); font-weight: 500; }
.carousel-dots { display: flex; gap: 8px; justify-content: center; margin-top: 24px; }
.carousel-dot {
  width: 10px; height: 10px; border-radius: 50%;
  background: var(--border-color); border: none; cursor: pointer;
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--accent-blue); transform: scale(1.2); }

/* ---- DATA LIFECYCLE DIAGRAM ---- */
.lifecycle-diagram {
  display: flex; align-items: center; justify-content: center;
  gap: 12px; margin-top: 48px; flex-wrap: wrap;
}
.lifecycle-node {
  background: var(--card-bg); border: 1px solid var(--border-color);
